@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --bg-dark: #0F0F0F;
  --bg-card: #1C1C1C;
  --bg-hover: #2A2A2A;
  --text-primary: #FFFFFF;
  --text-secondary: #A0A0A0;
  --accent-blue: #2962FF;
  --accent-hover: #1e4bd8;
  --negative-red: #F7525F;
  --positive-green: #089981;
  --border-color: #2E2E2E;
  --font-family: 'Inter', sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-dark);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

button {
  cursor: pointer;
  font-family: var(--font-family);
  border: none;
  background: none;
  color: inherit;
}

/* Typography */
h1 { font-size: 2.5rem; font-weight: 700; line-height: 1.2; }
h2 { font-size: 1.5rem; font-weight: 600; }
h3 { font-size: 1.125rem; font-weight: 600; }
.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-muted { color: var(--text-secondary); }

/* Utilities */
.flex { display: flex; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.gap-1 { gap: 0.25rem; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.w-full { width: 100%; }
.h-full { height: 100%; }

.text-positive { color: var(--positive-green); }
.text-negative { color: var(--negative-red); }
.bg-positive-dim { background-color: rgba(8, 153, 129, 0.1); color: var(--positive-green); }
.bg-negative-dim { background-color: rgba(247, 82, 95, 0.1); color: var(--negative-red); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 1rem;
  border-radius: 6px;
  font-weight: 500;
  transition: all 0.2s ease;
}
.btn-primary {
  background-color: var(--accent-blue);
  color: white;
}
.btn-primary:hover {
  background-color: var(--accent-hover);
}
.btn-secondary {
  background-color: var(--bg-hover);
  color: var(--text-primary);
}
.btn-secondary:hover {
  background-color: var(--border-color);
}
.btn-outline {
  border: 1px solid var(--border-color);
}
.btn-outline:hover {
  background-color: var(--bg-hover);
}

/* Navigation */
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1.5rem;
  height: 64px;
  border-bottom: 1px solid var(--border-color);
  background-color: var(--bg-dark);
  position: sticky;
  top: 0;
  z-index: 100;
}
.brand {
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.nav-links {
  display: flex;
  gap: 1.5rem;
}
.nav-links a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color 0.2s;
}
.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
}

/* Layout */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

/* Cards */
.card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1rem;
}

/* Tables */
.table-container {
  width: 100%;
  overflow-x: auto;
}
table {
  width: 100%;
  border-collapse: collapse;
}
th, td {
  padding: 0.75rem 1rem;
  text-align: left;
  border-bottom: 1px solid var(--border-color);
  font-size: 0.875rem;
}
th {
  color: var(--text-secondary);
  font-weight: 500;
}
tr:hover td {
  background-color: rgba(255, 255, 255, 0.02);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 1.5rem;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 1.5rem;
  overflow-x: auto;
}
.tab {
  padding: 0.75rem 0;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  white-space: nowrap;
}
.tab:hover {
  color: var(--text-primary);
}
.tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}
.tab-content {
  display: none;
}
.tab-content.active {
  display: block;
}

/* Specific Pages */
.hero {
  text-align: center;
  padding: 4rem 0;
  max-width: 800px;
  margin: 0 auto;
}
.hero h1 {
  margin-bottom: 1rem;
}
.hero p {
  color: var(--text-secondary);
  font-size: 1.125rem;
  margin-bottom: 2rem;
}

/* Footer */
footer {
  border-top: 1px solid var(--border-color);
  padding: 3rem 1.5rem;
  margin-top: 4rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 2rem;
  max-width: 1280px;
  margin: 0 auto;
}
.footer-col h4 {
  font-size: 0.875rem;
  margin-bottom: 1rem;
  color: var(--text-primary);
}
.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.footer-col a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}
.footer-col a:hover {
  color: var(--text-primary);
}

/* Chart Workspace */
.workspace {
  display: grid;
  grid-template-columns: 60px 1fr 300px;
  height: calc(100vh - 64px);
  overflow: hidden;
}
.toolbar {
  border-right: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 1rem 0;
  gap: 1rem;
}
.toolbar button {
  width: 40px;
  height: 40px;
  border-radius: 4px;
  color: var(--text-secondary);
}
.toolbar button:hover {
  background-color: var(--bg-hover);
  color: var(--text-primary);
}
.chart-area {
  display: flex;
  flex-direction: column;
}
.chart-header {
  height: 50px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  padding: 0 1rem;
  gap: 1rem;
}
.main-chart {
  flex: 1;
  background: var(--bg-dark);
  position: relative;
  /* Pattern to look like chart grid */
  background-image: 
    linear-gradient(var(--border-color) 1px, transparent 1px),
    linear-gradient(90deg, var(--border-color) 1px, transparent 1px);
  background-size: 50px 50px;
  background-position: -1px -1px;
}
.sidebar {
  border-left: 1px solid var(--border-color);
  background-color: var(--bg-card);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

/* Accordion */
.accordion-header {
  padding: 0.75rem 1rem;
  background-color: var(--bg-hover);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  font-weight: 600;
  border-bottom: 1px solid var(--border-color);
}
.accordion-content {
  display: none;
}
.accordion-content.expanded {
  display: block;
}
.watchlist-item {
  display: flex;
  justify-content: space-between;
  padding: 0.5rem 1rem;
  border-bottom: 1px solid var(--border-color);
  font-size: 0.875rem;
}
.watchlist-item:hover {
  background-color: var(--bg-hover);
}

/* Badges */
.badge {
  display: inline-block;
  padding: 0.125rem 0.375rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 500;
}

/* Toggle */
.toggle-switch {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
}
.toggle-track {
  width: 36px;
  height: 20px;
  background-color: var(--bg-hover);
  border-radius: 10px;
  position: relative;
  transition: background-color 0.2s;
}
.toggle-switch input { display: none; }
.toggle-switch input:checked + .toggle-track {
  background-color: var(--accent-blue);
}
.toggle-thumb {
  width: 16px;
  height: 16px;
  background-color: white;
  border-radius: 50%;
  position: absolute;
  top: 2px;
  left: 2px;
  transition: transform 0.2s;
}
.toggle-switch input:checked + .toggle-track .toggle-thumb {
  transform: translateX(16px);
}

/* Mini Chart placeholder */
.mini-chart {
  width: 60px;
  height: 20px;
  position: relative;
}
.mini-chart-up {
  background: linear-gradient(0deg, rgba(8, 153, 129, 0) 0%, rgba(8, 153, 129, 0.2) 100%);
  border-top: 2px solid var(--positive-green);
}
.mini-chart-down {
  background: linear-gradient(0deg, rgba(247, 82, 95, 0) 0%, rgba(247, 82, 95, 0.2) 100%);
  border-top: 2px solid var(--negative-red);
}

/* Idea Cards */
.idea-card {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.idea-card img {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
  border-radius: 4px;
  background-color: var(--bg-hover);
}

/* Grid Layouts */
.grid-cols-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.grid-cols-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.grid-cols-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }

@media (max-width: 1024px) {
  .workspace {
    grid-template-columns: 1fr;
    height: auto;
  }
  .toolbar, .sidebar {
    display: none; /* Simplification for responsive */
  }
}
@media (max-width: 768px) {
  .grid-cols-3, .grid-cols-4 { grid-template-columns: 1fr; }
  .grid-cols-2 { grid-template-columns: 1fr; }
  .nav-links { display: none; }
}

document.addEventListener('DOMContentLoaded', () => {
  // Tabs functionality
  const tabContainers = document.querySelectorAll('.tabs');

  tabContainers.forEach(container => {
    const tabs = container.querySelectorAll('.tab');

    tabs.forEach(tab => {
      tab.addEventListener('click', (e) => {
        // Remove active class from all tabs in this container
        tabs.forEach(t => t.classList.remove('active'));

        // Add active class to clicked tab
        const clickedTab = e.currentTarget;
        clickedTab.classList.add('active');

        // Check if there are corresponding content sections
        const targetId = clickedTab.getAttribute('data-target');
        if (targetId) {
          // Find the parent section or document to scope the content search
          const contentSections = document.querySelectorAll('.tab-content[data-group="' + clickedTab.getAttribute('data-group') + '"]');
          contentSections.forEach(content => {
            content.classList.remove('active');
            if (content.id === targetId) {
              content.classList.add('active');
            }
          });
        }
      });
    });
  });

  // Accordion functionality
  const accordions = document.querySelectorAll('.accordion-header');
  accordions.forEach(acc => {
    acc.addEventListener('click', () => {
      const content = acc.nextElementSibling;
      const icon = acc.querySelector('i.ri-arrow-down-s-line, i.ri-arrow-right-s-line');

      if (content.classList.contains('expanded')) {
        content.classList.remove('expanded');
        if (icon) {
          icon.classList.remove('ri-arrow-down-s-line');
          icon.classList.add('ri-arrow-right-s-line');
        }
      } else {
        content.classList.add('expanded');
        if (icon) {
          icon.classList.remove('ri-arrow-right-s-line');
          icon.classList.add('ri-arrow-down-s-line');
        }
      }
    });
  });

  // Navigation active state
  const currentPath = window.location.pathname.split('/').pop() || 'index.html';
  const navLinks = document.querySelectorAll('.nav-links a');
  navLinks.forEach(link => {
    if (link.getAttribute('href') === currentPath) {
      link.classList.add('active');
    }
  });
});
